// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // ensure parameter lengths match and are non-empty as required by the contract
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // deploy an adversarial helper that implements the correct transferFrom interface and returns false
        AdversarialToken token = new AdversarialToken();
        // ensure caddress is the adversarial token to manifest the difference
        vm.assume(caddress == address(token));
        // ensure the same length for both arrays to avoid revert in the loop
        // call C with the fuzzed parameters and capture success
        bool result = c.transfer(from, caddress, _tos, v);
        // the correct contract returns true for successful calls; the buggy one returns false because the selector mismatch causes the token's fallback to revert
        assertTrue(result);
    }
}

contract AdversarialToken {
    // implements transferFrom(address,address,uint256) which returns true (success)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    // fallback reverts for any unexpected call, including the buggy selector
    fallback() external payable {
        revert("unknown selector");
    }
}
